import {$,$$,esc,icon,hydrate,toast,dialog,closeDialog,empty,readStore,writeStore,safeUrl,fmt} from './ui.js';
import {api,session,saveSession,clearSession} from './client.js';
import {Player,itemKey,itemBody} from './audio-player.js';

const nav=[['home','Home','home'],['search','Explore','search'],['quran','The Quran','book'],['library','Your library','library']];
const state={surahs:[],reciters:[],tracks:[],playlists:[],likes:new Set(),items:new Map(),viewItems:[],settings:{city:'',country:'',method:3,reciter_id:1,translation:true,...readStore('hfm_settings',{})},quranView:readStore('hfm_quran_view','list'),surahFilter:'all',surahQuery:'',juz:'',routeVersion:0,prayer:null};
let currentPlaylist=null,readerAyahs=[],readerSurah=null;
const defaultSettings=()=>({city:'',country:'',method:3,reciter_id:1,translation:true});
let catalogueLoaded=false;
const remember=item=>{state.items.set(itemKey(item),item);return item};
const reciter=()=>state.reciters.find(r=>r.id===Number(state.settings.reciter_id)&&r.audio_available)||state.reciters.find(r=>r.audio_available);
function surahItem(s,r=reciter()){return remember({type:'surah',id:s.id,reciter_id:r.id,title:'Surah '+s.name_en,title_ar:s.name_ar,subtitle:r.name,audio_url:r.audio_base_url? r.audio_base_url+String(s.id).padStart(3,'0')+'.mp3':null,link_url:r.link_url})}
function trackItem(t){return remember({type:'track',id:t.id,title:t.title,subtitle:t.artist,track_type:t.type,audio_url:t.audio_url,link_url:t.link_url,cover_url:t.cover_url})}
const b=(name,action,label,attrs='')=>`<button class="icon-button" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${icon(name)}</button>`;
const actionButton=(name,label,action,key,cls='')=>`<button class="button ${cls}" data-action="${action}" ${key?`data-key="${esc(key)}"`:''}>${icon(name)}${esc(label)}</button>`;
const subheading=(title,subtitle='',link='',label='View all')=>`<div class="section-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${link?`<a class="text-link" href="${esc(link)}">${esc(label)} ${icon('arrow')}</a>`:''}</div>`;
function intro(kicker,title,description='',extra=''){return `<div class="page-intro"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${extra}</div>`;}
const likeButton=item=>b('heart','like',state.likes.has(itemKey(item))?'Unlike':'Like',`data-key="${itemKey(item)}" aria-pressed="${state.likes.has(itemKey(item))}"`);
function miniRow(item,i,options={}){remember(item);return `<div class="mini-row" data-row-key="${itemKey(item)}"><span class="number">${String(i+1).padStart(2,'0')}</span><button class="text-button item-title" data-action="${item.audio_url?'play':'source'}" data-key="${itemKey(item)}"><strong>${esc(item.title)}</strong><small>${esc(item.subtitle)}</small></button>${item.title_ar?`<span class="arabic" lang="ar">${esc(item.title_ar)}</span>`:''}${options.reorder?b('up','move-up','Move up',`data-index="${i}" ${i===0?'disabled':''}`)+b('down','move-down','Move down',`data-index="${i}" ${i===state.viewItems.length-1?'disabled':''}`):''}${b(item.audio_url?'play':'external',item.audio_url?'play':'source',item.audio_url?'Play '+item.title:'Open source for '+item.title,`data-key="${itemKey(item)}"`)}${options.remove?b('trash','remove-item','Remove from playlist',`data-entry="${item.entry_id}"`):likeButton(item)}${b('more','item-menu','More options for '+item.title,`data-key="${itemKey(item)}"`)}</div>`;}
function reciterCard(r){return `<a class="reciter-card" href="${r.audio_available?'#/quran?reciter='+r.id:r.link_url}" ${r.audio_available?'':'target="_blank" rel="noopener noreferrer"'}><div class="reciter-avatar" aria-hidden="true">${esc(r.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><h3>${esc(r.name)}</h3><p>${esc(r.country)}${!r.audio_available?' · External':''}</p></a>`;}
const videoId=item=>{try{const u=new URL(item.link_url);return ['www.youtube.com','youtube.com'].includes(u.hostname)&&/^[\w-]{11}$/.test(u.searchParams.get('v'))?u.searchParams.get('v'):null}catch{return null}};
function trackCard(t,i){const item=trackItem(t);return `<article class="track-card"><button class="cover-button" data-action="${item.audio_url?'play':'source'}" data-key="${itemKey(item)}" aria-label="${item.audio_url?'Play':'Open source for'} ${esc(t.title)}"><div class="cover variant-${i%4}"><span class="arabic" lang="ar">${t.type==='naat'?'محبّة':'سكينة'}</span><span class="cover-label">${t.type==='naat'?'WORDS OF DEVOTION':'MOMENTS OF PEACE'}</span></div></button><h3>${esc(t.title)}</h3><p>${esc(t.artist)}</p><div class="track-meta"><span class="source-label">${item.audio_url?'Audio':videoId(item)?'YouTube recording':'Find recording'}</span><span>${likeButton(item)}${b('plus','add-playlist','Add to playlist',`data-key="${itemKey(item)}"`)}</span></div></article>`;}
function collectionCard(title,text,href,name='book',cls=''){return `<a class="collection-card ${cls}" href="${href}">${icon(name)}<h3>${esc(title)}</h3><p>${esc(text)}</p></a>`;}
function syncLikes(){
 $$('[data-action="like"]').forEach(btn=>{const liked=state.likes.has(btn.dataset.key);btn.classList.toggle('active',liked);btn.setAttribute('aria-pressed',String(liked));btn.setAttribute('aria-label',liked?'Unlike':'Like');});
 const current=Player.current,liked=current&&state.likes.has(itemKey(current));$('#player-like').classList.toggle('active',!!liked);$('#player-like').setAttribute('aria-pressed',String(!!liked));
}
function syncPlaying(){syncNowPlaying();$$('[data-row-key]').forEach(row=>{const on=row.dataset.rowKey===itemKey(Player.current);row.classList.toggle('is-current',on);const btn=$('[data-action="play"]',row);if(btn&&btn.classList.contains('icon-button'))btn.innerHTML=icon(on&&!Player.audio.paused?'pause':'play');});const modalPlay=$('#modal [data-action="toggle-play"]');if(modalPlay)modalPlay.innerHTML=icon(Player.audio.paused?'play':'pause')+(Player.audio.paused?'Play':'Pause');syncLikes();if(!$('#queue-panel').hidden)renderQueue();}
async function loadLibrary(){
 if(!session.token){state.playlists=[];state.likes.clear();renderSidebar();return;}
 const owner=session.user.id;const [p,l]=await Promise.all([api('/playlists'),api('/likes')]);if(owner!==session.user?.id)return;state.playlists=p.playlists;state.likes=new Set(l.likes.map(itemKey));l.likes.forEach(remember);renderSidebar();syncLikes();
}
function renderSidebar(){
 $('#playlist-nav').innerHTML=state.playlists.length?state.playlists.map(p=>`<a class="nav-link" href="#/playlist/${p.id}"><span class="playlist-dot"></span><span class="playlist-name">${esc(p.name)}</span></a>`).join(''):`<p class="playlist-hint">${session.user?'Create a playlist for your quiet moments.':'Sign in to make this space your own.'}</p>`;
 $('#account-link').innerHTML=session.user?`<span class="initial">${esc(session.user.name[0].toUpperCase())}</span><span class="account-name">${esc(session.user.name.split(' ')[0])}</span>`:'Sign in';
 $('#account-link').href=session.user?'#/account':'#/login';
}
function requireUser(){if(session.user)return true;location.hash='#/login';return false;}
async function home(){
 const version=state.routeVersion;
 const d=await api('/home?timezone='+encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone));const today=state.surahs.find(s=>s.id===d.surah_of_the_day.id)||state.surahs[0];const daily=surahItem(today);
 if(version!==state.routeVersion)return '';
 const bookmark=readStore('hfm_bookmark_'+(session.user?.id||'guest'),null);
 const quick=[{id:18,label:'Al-Kahf',sub:'A moment of reflection',ic:'book'},{id:36,label:'Ya-Sin',sub:'83 verses to reflect on',ic:'headphones'},{id:55,label:'Ar-Rahman',sub:'The Most Merciful',ic:'moon'}];
 const recent=d.recently_played.length?d.recently_played.map(remember):[1,67,112,113].map(id=>surahItem(state.surahs.find(s=>s.id===id)));
 state.viewItems=recent;
 return `<div class="welcome"><div><div class="eyebrow">A MOMENT FOR YOUR SOUL</div><h1>Assalamu Alaikum${session.user?`, <span>${esc(session.user.name.split(' ')[0])}</span>`:'.'}</h1><p>Slow down. Listen deeply. Find your way back to peace.</p></div><span class="arabic" lang="ar">السلام عليكم ورحمة الله</span></div>
 ${bookmark?`<p class="reader-notice">${icon('bookmark')} Continue reading: <a class="text-link" href="#/read/${Number(bookmark.surah)}?ayah=${Number(bookmark.ayah)}">${esc(bookmark.name)} · verse ${Number(bookmark.ayah)}</a></p><br>`:''}<section class="hero"><img class="hero-art" src="/assets/sanctuary.svg" alt=""><span class="hero-title-ar arabic" lang="ar">${esc(today.name_ar)}</span><div class="hero-copy"><div class="eyebrow">${icon('sun')} YOUR DAILY RECITATION</div><h2>A little stillness.<br><em>A deeper connection.</em></h2><p>Let the verses of ${esc(today.name_en)} bring a moment of reflection to your day.</p><div class="hero-actions">${actionButton('play','Listen now','play',itemKey(daily),'primary')}<a class="button ghost" href="#/read/${today.id}">${icon('book')}Read the surah</a></div></div><span class="hero-caption">${today.ayah_count} VERSES · ${esc(today.meaning).toUpperCase()}</span></section>
 <div class="quick-grid">${quick.map(q=>{const it=surahItem(state.surahs.find(s=>s.id===q.id));return `<button class="quick-card" data-action="play" data-key="${itemKey(it)}"><span class="quick-symbol">${icon(q.ic)}</span><span><h3>Surah ${q.label}</h3><p>${q.sub}</p></span>${icon('play')}</button>`}).join('')}</div>
 <div class="home-split"><section class="section">${subheading(d.recently_played.length?'Pick up where you left off':'Begin with a recitation',d.recently_played.length?'Your recently played recitations':'Familiar verses. A fresh moment of calm.','#/library?tab=history','See all')}<div class="mini-list">${recent.slice(0,4).map((x,i)=>miniRow(x,i)).join('')}</div></section><section class="prayer-card" id="prayer-home">${prayerMarkup()}</section></div>
 <section class="section">${subheading('Voices that bring you closer','Find a reciter that speaks to your heart.','#/reciters','All reciters')}<div class="reciter-grid">${state.reciters.filter(r=>r.audio_available).slice(0,6).map(reciterCard).join('')}</div></section>
 <section class="section">${subheading('Words of peace','Nasheeds for the moments in between.','#/tracks?type=nasheed','Explore nasheeds')}<div class="track-grid">${state.tracks.filter(t=>t.type==='nasheed').slice(0,4).map(trackCard).join('')}</div></section>`;
}
function prayerMarkup(){
 if(!state.settings.city||!state.settings.country)return `<div class="eyebrow">${icon('pin')} A RHYTHM FOR YOUR DAY</div><h3 class="section">Your local prayer times</h3><p>Add your city to see daily prayer times, wherever you call home.</p><a href="#/account?section=preferences" class="button ghost small">${icon('pin')}Set your location</a>`;
 if(!state.prayer)return `<h3>${icon('sun')} Prayer times</h3><p>${esc(state.settings.city)}</p><p>Loading your local schedule…</p>`;
 if(state.prayer.error)return `<h3>Prayer times</h3><p>${esc(state.prayer.error)}</p><button class="button small" data-action="refresh-prayer">Try again</button>`;
 const d=state.prayer;return `<div><div class="eyebrow">DAILY PRAYER TIMES</div><h3 class="section">${esc(d.city)}</h3><p>${esc(d.date.gregorian.readable)} · ${esc(d.timezone)}</p></div>${['Fajr','Dhuhr','Asr','Maghrib','Isha'].map(name=>`<div class="prayer-line"><span>${name}</span><strong>${esc(d.timings[name])}</strong></div>`).join('')}<p>${esc(d.method)} · AlAdhan</p><a class="text-link" href="#/account?section=preferences">Change location</a>`;
}
async function refreshPrayer(){if(!state.settings.city||!state.settings.country)return;try{state.prayer=await api('/prayer?'+new URLSearchParams({city:state.settings.city,country:state.settings.country,method:state.settings.method}));}catch(e){state.prayer={error:e.message};}if($('#prayer-home'))$('#prayer-home').innerHTML=prayerMarkup();}
function surahRows(){
 const q=state.surahQuery.toLowerCase().trim();const list=state.surahs.filter(s=>(state.surahFilter==='all'||s.revelation_type===state.surahFilter)&&(!state.juz||s.juz===Number(state.juz))&&(!q||String(s.id)===q||[s.name_en,s.name_ar,s.meaning].join(' ').toLowerCase().includes(q)));
 state.viewItems=list.map(s=>surahItem(s));
 return {count:list.length,html:list.length?`<div class="${state.quranView==='grid'?'surah-grid':'surah-table'}">${state.quranView!=='grid'?'<div class="table-head"><span>#</span><span>Surah</span><span>Arabic</span><span class="detail-head">Revelation</span><span class="detail-head">Juz</span><span>Listen & save</span></div>':''}${list.map((s,i)=>{const item=state.viewItems[i];return `<div class="surah-row" data-row-key="${itemKey(item)}"><span class="surah-number">${String(s.id).padStart(2,'0')}</span><a class="surah-name" href="#/read/${s.id}"><strong class="surah-title">${esc(s.name_en)}</strong><p class="surah-meaning">${esc(s.meaning)} · ${s.ayah_count} verses</p></a><a href="#/read/${s.id}" class="arabic" lang="ar">${esc(s.name_ar)}</a><span class="surah-details">${s.revelation_type}</span><span class="surah-details">${s.juz}</span><span class="surah-actions">${b('play','play','Play '+s.name_en,`data-key="${itemKey(item)}"`)}${likeButton(item)}${b('plus','add-playlist','Add '+s.name_en+' to playlist',`data-key="${itemKey(item)}"`)}</span></div>`}).join('')}</div>`:empty('No surahs found','Try a different name, number, or filter.')};
}
function quran(params){
 if(params.has('reciter')){const chosen=state.reciters.find(r=>r.id===Number(params.get('reciter'))&&r.audio_available);if(chosen){state.settings.reciter_id=chosen.id;writeStore('hfm_settings',state.settings)}}
 state.surahQuery=params.get('q')||'';state.surahFilter='all';state.juz='';const rows=surahRows();
 return `${intro('LISTEN. READ. REFLECT.','The Noble Quran','114 surahs, one timeless source of guidance.','<span class="arabic" lang="ar">القرآن الكريم</span>')}<div class="toolbar"><input id="surah-search" type="search" aria-label="Filter surahs" placeholder="Search by name, meaning or number" value="${esc(state.surahQuery)}"><select id="reciter-select" aria-label="Choose reciter">${state.reciters.filter(r=>r.audio_available).map(r=>`<option value="${r.id}" ${r.id===reciter().id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><div class="toggle-group">${b('list','quran-list','List view')}${b('grid','quran-grid','Grid view')}</div></div><div class="row-between"><div class="chips">${['all','Makki','Madani'].map(x=>`<button class="chip ${x==='all'?'active':''}" data-action="surah-filter" data-filter="${x}">${x==='all'?'All surahs':x}</button>`).join('')}</div><select id="juz-filter" aria-label="Filter by starting Juz"><option value="">Starts in any Juz</option>${Array.from({length:30},(_,i)=>`<option value="${i+1}">Starts in Juz ${i+1}</option>`).join('')}</select></div><p class="result-count" id="result-count">${rows.count} surahs · Recited by ${esc(reciter().name)}</p><div id="surah-results">${rows.html}</div>`;
}
function updateSurahs(){const result=surahRows();$('#surah-results').innerHTML=result.html;$('#result-count').textContent=result.count+' surahs · Recited by '+reciter().name;$$('[data-action="surah-filter"]').forEach(el=>el.classList.toggle('active',el.dataset.filter===state.surahFilter));$$('[data-action^="quran-"]').forEach(el=>el.classList.toggle('active',el.dataset.action==='quran-'+state.quranView));syncPlaying();}
async function reader(id,params){
 const version=state.routeVersion;
 const s=state.surahs.find(x=>x.id===Number(id));if(!s)return empty('Surah not found','Choose a surah from the Quran catalogue.','<a class="button primary" href="#/quran">Browse Quran</a>');
 readerSurah=s;const item=surahItem(s);state.viewItems=[item];let body;
 try{const data=await api('/surahs/'+s.id+'/ayahs');if(version!==state.routeVersion)return '';readerAyahs=data.ayahs;body=data.ayahs.map(a=>`<article class="ayah ${Number(params.get('ayah'))===a.number?'highlighted':''}" id="ayah-${a.number}"><div class="ayah-meta"><span class="ayah-number">${s.id}:${a.number}</span><span class="spacer"></span>${b('bookmark','bookmark-ayah','Bookmark verse '+a.number,`data-ayah="${a.number}"`)}${b('copy','copy-ayah','Copy verse '+a.number,`data-ayah="${a.number}"`)}</div><p class="arabic" lang="ar">${esc(a.arabic)}</p><p class="translation" ${state.settings.translation?'':'hidden'}>${esc(a.english)}</p></article>`).join('');}
 catch(e){readerAyahs=[];body=empty('The text could not be loaded',e.message,`<button class="button primary" data-action="retry">Try again</button>`);}
 return `<a class="text-link" href="#/quran">${icon('back')}All surahs</a><div class="reader-header section"><div class="eyebrow">SURAH ${s.id} · ${s.revelation_type.toUpperCase()} · ${s.ayah_count} VERSES</div><div class="arabic" lang="ar">${esc(s.name_ar)}</div><h1>${esc(s.name_en)}</h1><p>${esc(s.meaning)}</p><div class="row">${actionButton('play','Listen to surah','play',itemKey(item),'primary')}${actionButton('plus','Add to playlist','add-playlist',itemKey(item),'ghost')}</div></div><div class="toolbar"><label class="checkbox-label"><input id="translation-toggle" type="checkbox" ${state.settings.translation?'checked':''}>English translation</label><span class="spacer"></span><select id="verse-jump" aria-label="Jump to verse"><option value="">Jump to verse</option>${Array.from({length:s.ayah_count},(_,i)=>`<option value="${i+1}">Verse ${i+1}</option>`).join('')}</select></div><p class="reader-notice">Arabic text: Uthmani · English: Sahih International · <a href="https://alquran.cloud" target="_blank" rel="noopener noreferrer">AlQuran Cloud</a>. Audio plays the full surah; the reading view scrolls independently.</p>${body}<div class="row-between section">${s.id>1?`<a class="button ghost small" href="#/read/${s.id-1}">${icon('back')}Previous surah</a>`:'<span></span>'}${s.id<114?`<a class="button ghost small" href="#/read/${s.id+1}">Next surah${icon('chevron')}</a>`:''}</div>`;
}
async function search(params){
 const version=state.routeVersion;
 const q=params.get('q')?.trim()||'';
 if(!q)return `${intro('FOLLOW YOUR CURIOSITY','Explore your sanctuary','Find a familiar voice, a favourite surah, or something new.')}<div class="collection-grid">${collectionCard('The Noble Quran','114 surahs, in Arabic and English','#/quran')}${collectionCard('Beautiful recitations','Explore our reciter collection','#/reciters','headphones')}${collectionCard('Nasheeds','Voices of peace and reflection','#/tracks?type=nasheed','music','purple')}${collectionCard('Naats & devotion','Words that bring you closer','#/tracks?type=naat','moon','gold')}</div><section class="section">${subheading('A good place to start')}<div class="chips">${['Al-Fatihah','Al-Kahf','Mishary','Ar-Rahman','Forgive Me'].map(t=>`<a class="chip" href="#/search?q=${encodeURIComponent(t)}">${esc(t)}</a>`).join('')}</div></section>`;
 const d=await api('/tracks/search?q='+encodeURIComponent(q));if(version!==state.routeVersion)return '';state.viewItems=[...d.surahs.map(s=>surahItem(s)),...d.tracks.map(trackItem)];
 return `${intro('YOUR SEARCH',q,`${d.surahs.length+d.reciters.length+d.tracks.length} results`)}${!state.viewItems.length&&!d.reciters.length?empty('No results yet','Try a surah name, reciter, artist, or track title.'):''}${d.surahs.length?`<section class="section">${subheading('Surahs')}<div class="mini-list">${d.surahs.map((s,i)=>miniRow(surahItem(s),i)).join('')}</div></section>`:''}${d.reciters.length?`<section class="section">${subheading('Reciters')}<div class="reciter-grid">${d.reciters.map(r=>reciterCard(state.reciters.find(x=>x.id===r.id))).join('')}</div></section>`:''}${d.tracks.length?`<section class="section">${subheading('Nasheeds & Naats')}<div class="track-grid">${d.tracks.map(trackCard).join('')}</div></section>`:''}`;
}
function tracks(params){const type=params.get('type')==='naat'?'naat':'nasheed',list=state.tracks.filter(t=>t.type===type);state.viewItems=list.map(trackItem);return `${intro('WORDS THAT STAY WITH YOU',type==='naat'?'Naats & devotion':'Peaceful nasheeds',`${list.length} recordings to discover. Save your favourites to your library.`)}<div class="chips"><a class="chip ${type==='nasheed'?'active':''}" href="#/tracks?type=nasheed">Nasheeds</a><a class="chip ${type==='naat'?'active':''}" href="#/tracks?type=naat">Naats</a></div><p class="reader-notice">Recordings open in their source player. Entries marked “Find recording” open a search for that artist and title.</p><div class="track-grid section">${list.map(trackCard).join('')}</div>`;}
async function library(params){
 const version=state.routeVersion;
 if(!session.user)return empty('Your own little sanctuary','Sign in to keep favourite recitations, personal playlists, and listening history in one place.','<a href="#/login" class="button primary">Sign in</a>');
 const tab=params.get('tab')||'playlists';let html;
 if(tab==='liked'){const d=await api('/likes');if(version!==state.routeVersion)return '';state.viewItems=d.likes.map(remember);html=state.viewItems.length?`<div class="actions-row">${actionButton('play','Play recitations','play-all',null,'primary')}</div><div class="mini-list">${state.viewItems.map((x,i)=>miniRow(x,i)).join('')}</div>`:empty('Keep what speaks to you','Tap the heart beside a recitation to find it here.','<a class="button primary" href="#/quran">Explore the Quran</a>');}
 else if(tab==='history'){const d=await api('/history?limit=200');if(version!==state.routeVersion)return '';state.viewItems=d.history.map(remember);html=state.viewItems.length?`<div class="actions-row">${actionButton('play','Play recitations','play-all',null,'primary')}<span class="spacer"></span><button class="button ghost small" data-action="clear-history">Clear history</button></div><div class="mini-list">${state.viewItems.map((x,i)=>miniRow(x,i)).join('')}</div>`:empty('The start of your journey','Your listening history appears here when you play a recitation.');}
 else {const bookmark=readStore('hfm_bookmark_'+session.user.id,null);html=`${bookmark?`<div class="reader-notice">Your reading bookmark: <a class="text-link" href="#/read/${bookmark.surah}?ayah=${bookmark.ayah}">${esc(bookmark.name)} · verse ${bookmark.ayah}</a></div>`:''}<div class="collection-grid section">${state.playlists.map(p=>collectionCard(p.name,p.item_count+' saved items','#/playlist/'+p.id,'queue')).join('')}<button class="collection-card text-button" data-action="create-playlist">${icon('plus')}<h3>Create a playlist</h3><p>A new space for your favourites.</p></button></div>`;}
 return `${intro('MADE FOR YOU','Your library','A home for the recitations you return to.')}<div class="chips">${[['playlists','Playlists'],['liked','Liked'],['history','Recently played']].map(([key,label])=>`<a class="chip ${tab===key?'active':''}" href="#/library?tab=${key}">${label}</a>`).join('')}</div><section class="section">${html}</section>`;
}
async function playlist(id){
 const version=state.routeVersion;
 if(!session.user)return library(new URLSearchParams());const d=await api('/playlists/'+id);if(version!==state.routeVersion)return '';currentPlaylist=d;state.viewItems=d.items.map(remember);
 return `<a class="text-link" href="#/library">${icon('back')}Your library</a><div class="library-heading section">${icon('queue')}<div><div class="eyebrow">YOUR PLAYLIST</div><h1>${esc(d.name)}</h1><p>${d.items.length} saved items · Curated by ${esc(session.user.name)}</p></div></div><div class="actions-row">${actionButton('play','Play recitations','play-all',null,'primary')}<button class="button ghost small" data-action="rename-playlist">${icon('edit')}Rename</button><span class="spacer"></span><button class="button ghost small" data-action="delete-playlist">${icon('trash')}Delete</button></div>${d.items.length?`<p class="result-count">Use the arrows to change the listening order.</p><div class="mini-list section">${state.viewItems.map((x,i)=>miniRow(x,i,{remove:true,reorder:true})).join('')}</div>`:empty('Make it yours','Add recitations with the + button while browsing the Quran.','<a class="button primary" href="#/quran">Browse recitations</a>')}`;
}
function passwordField(label,name,autocomplete='current-password'){return `<label class="field-label">${label}<div class="password-field"><input class="field" name="${name}" type="password" required minlength="${autocomplete==='new-password'?8:1}" maxlength="128" autocomplete="${autocomplete}"><button class="icon-button" type="button" data-action="show-password" aria-label="Show password">Show</button></div></label>`;}
function auth(signup=false){
 if(session.user)return empty('You’re already signed in','Your library is ready whenever you are.','<a href="#/home" class="button primary">Go home</a>');
 return `<div class="auth-wrap"><div class="auth-art"><div class="eyebrow">WELCOME TO HIDAYAH FM</div><h1>A place to pause.<br>A way to<br><em>reconnect.</em></h1><p>Bring a little more reflection to your day, one recitation at a time.</p></div><section class="auth-form"><img src="/assets/logo.svg" width="42" height="42" alt="Hidayah FM"><h2>${signup?'Begin your journey':'Welcome back'}</h2><p>${signup?'Create your personal sanctuary. It’s free.':'Sign in to open your personal sanctuary.'}</p><form id="auth-form" data-mode="${signup?'signup':'login'}">${signup?'<label class="field-label">Your name<input class="field" name="name" autocomplete="name" minlength="2" maxlength="60" placeholder="How should we greet you?" required></label>':''}<label class="field-label">Email address<input class="field" name="email" type="email" maxlength="254" autocomplete="email" placeholder="you@example.com" required></label>${passwordField('Password','password',signup?'new-password':'current-password')}${signup?passwordField('Confirm password','confirm','new-password'):''}${signup?'<label class="checkbox-label"><input type="checkbox" name="terms" required><span>I have read the <a class="text-link" href="#/privacy">privacy information</a>.</span></label>':''}<p class="form-error" role="alert"></p><button class="button primary" type="submit">${signup?'Create account':'Sign in'}${icon('arrow')}</button></form><p class="auth-switch">${signup?'Already have an account? <a href="#/login">Sign in</a>':'New here? <a href="#/signup">Create an account</a>'}</p>${!signup?'<p class="dialog-copy"><button class="text-link" type="button" data-action="reset-password">Forgot your password?</button></p>':''}</section></div>`;
}
async function account(){
 const settings=state.settings;let stats={plays:0,completed_surahs:0};if(session.user)stats=await api('/history/stats');
 return `${intro('YOUR SANCTUARY, YOUR WAY',session.user?'Account & preferences':'Listening preferences',session.user?'Manage your profile and make yourself at home.':'Set up your listening experience. Sign in to sync preferences.')} ${session.user?`<div class="stat-grid"><div class="stat-box"><strong>${state.playlists.length}</strong><span>Personal playlists</span></div><div class="stat-box"><strong>${state.likes.size}</strong><span>Saved favourites</span></div><div class="stat-box"><strong>${stats.completed_surahs}/114</strong><span>Surahs played to the end</span></div></div>`:'<p class="reader-notice"><a class="text-link" href="#/login">Sign in</a> or <a class="text-link" href="#/signup">create an account</a> to save your library.</p>'}<div class="form-grid section">${session.user?`<section class="form-panel"><h2>Your profile</h2><p>${esc(session.user.email)}</p><form id="profile-form"><label class="field-label">Your name<input class="field" name="name" value="${esc(session.user.name)}" minlength="2" maxlength="60" required autocomplete="name"></label><p class="form-error" role="alert"></p><button class="button primary" type="submit">Save profile</button></form></section><section class="form-panel"><h2>Change password</h2><p>Updating your password signs out your other sessions.</p><form id="password-form">${passwordField('Current password','current_password')}${passwordField('New password','new_password','new-password')}${passwordField('Confirm new password','confirm','new-password')}<p class="form-error" role="alert"></p><button class="button ghost" type="submit">Update password</button></form></section>`:''}<section class="form-panel wide" id="preferences"><h2>Listening & prayer preferences</h2><p>Prayer times are calculated for the city and method you choose. Check local mosque times for congregation arrangements.</p><form id="preferences-form"><div class="form-grid"><label class="field-label">City<input class="field" name="city" value="${esc(settings.city)}" maxlength="100" placeholder="e.g. London"></label><label class="field-label">Country<input class="field" name="country" value="${esc(settings.country)}" maxlength="100" placeholder="e.g. United Kingdom"></label><label class="field-label">Prayer calculation method<select name="method">${[[3,'Muslim World League'],[2,'Islamic Society of North America'],[1,'University of Islamic Sciences, Karachi'],[4,'Umm Al-Qura, Makkah'],[5,'Egyptian General Authority of Survey'],[7,'Institute of Geophysics, Tehran'],[8,'Gulf Region'],[9,'Kuwait'],[10,'Qatar'],[11,'Singapore'],[12,'France'],[13,'Turkey'],[14,'Russia'],[15,'Moonsighting Committee'],[16,'Dubai']].map(([id,label])=>`<option value="${id}" ${Number(settings.method)===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field-label">Default reciter<select name="reciter_id">${state.reciters.filter(r=>r.audio_available).map(r=>`<option value="${r.id}" ${r.id===reciter().id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div><label class="checkbox-label"><input name="translation" type="checkbox" ${settings.translation?'checked':''}>Show English translation in the reader</label><p class="form-error" role="alert"></p><button class="button primary" type="submit">Save preferences</button></form></section>${session.user?`<section class="form-panel wide"><h2>Your data</h2><p>Your account, playlists and history belong to you.</p><div class="actions-row"><button class="button ghost" data-action="export">${icon('download')}Export your data</button><button class="button ghost" data-action="logout">${icon('logout')}Sign out</button><span class="spacer"></span><button class="button danger small" data-action="delete-account">Delete account</button></div></section>`:''}</div>`;
}
function about(privacy=false){return (!session.user?'<p><a class="text-link" href="#/login">Sign in</a> · <a class="text-link" href="#/signup">Create account</a></p>':'')+intro(privacy?'YOUR SPACE. YOUR DATA.':'A LITTLE PEACE, EVERY DAY',privacy?'Privacy at Hidayah FM':'About Hidayah FM')+`<div class="prose">${privacy?`<h2>What is stored</h2><p>Firebase Authentication manages your email and password. Your profile, preferences, playlists, likes, playback progress, reading bookmark and listening history are stored privately in the Hidayah FM Firebase Realtime Database. Passwords are never stored in that database or included in account exports.</p><p>Your browser stores your Firebase sign-in session and a local cache of playback, volume, bookmarks and preferences. Your library, reading bookmark and playback position also sync to Firebase. Sign out on shared devices. You can export your library, clear listening history, or delete your account in Settings.</p><h2>External services</h2><p>Quran recordings stream from QuranicAudio or MP3Quran. Quran text and its English translation are included in the app as static files, sourced from AlQuran Cloud. Prayer times use AlAdhan; only your chosen city, country and calculation method are sent. These services receive the network information required to serve requests.</p><p>YouTube recordings are embedded only after you open a source. YouTube may set cookies or require consent according to its own policies. Search-only entries open a new tab. Hidayah FM does not enable Firebase Analytics or add its own advertising. External players follow their own policies.</p><h2>Deleting your account</h2><p>Account deletion removes your Firebase Authentication account and its profile, playlists, likes, preferences, bookmarks, playback state and history from the Firebase Realtime Database. Previously exported files or backups remain with their owners. Your browser playback and reading data are also cleared on deletion.</p>`:`<p>Hidayah FM is a personal space for Quran recitation, reading and devotional listening. Browse all 114 surahs, discover reciters, and curate a library of moments you want to return to.</p><p class="developer-credit">Created by Zuhair Mumtaz</p><h2>Audio & text sources</h2><ul><li><a href="https://quranicaudio.com" target="_blank" rel="noopener noreferrer">QuranicAudio</a> and <a href="https://mp3quran.net" target="_blank" rel="noopener noreferrer">MP3Quran</a>: complete-surah recordings.</li><li><a href="https://alquran.cloud" target="_blank" rel="noopener noreferrer">AlQuran Cloud</a>: Arabic Uthmani text and Sahih International English translation.</li><li><a href="https://aladhan.com" target="_blank" rel="noopener noreferrer">AlAdhan</a>: calculated prayer schedules.</li><li>Nasheeds and Naats: links to source videos and recordings, credited to their artists.</li></ul><p>Recordings remain hosted by their sources. Availability can change. Entries without a verified recording are labelled “Find recording”. The Quran reader scrolls independently of full-surah playback.</p><h2>A few helpful shortcuts</h2><p>Ctrl K opens search. Space plays or pauses when you are not typing. Use the player queue to arrange what comes next, and the moon button for a sleep timer.</p><h2>Your listening journey</h2><p>Listening history records audio that started playing. Completion counts a surah when playback reaches its end. These are listening statistics, not a measure of religious observance.</p>`}</div>`;}

async function route(){
 const version=++state.routeVersion;closeDialog();$('#sidebar').classList.remove('open');$('#menu-scrim').hidden=true;
 let raw=location.hash.replace(/^#\/?/,'')||(session.user?'home':'login');
 const publicPage=['login','signup','privacy'].includes(raw.split('?')[0]);
 document.body.classList.toggle('auth-locked',!session.user);
 if(!session.user&&!publicPage){history.replaceState(null,'','/#/login');raw='login';}const [path,query='']=raw.split('?'),parts=path.split('/'),page=parts[0],params=new URLSearchParams(query);
 $$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page||(page==='read'&&a.dataset.nav==='quran')||(page==='playlist'&&a.dataset.nav==='library'));if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 $('#global-search input').value=page==='search'?params.get('q')||'':'';
 $('#main').innerHTML='<div class="loading-state" role="status">Loading…</div>';state.viewItems=[];currentPlaylist=null;
 document.title=({home:'Home',quran:'The Quran',read:'Read the Quran',search:'Explore',library:'Your library',playlist:'Your playlist',account:'Account',tracks:'Devotional recordings',reciters:'Reciters',login:'Sign in',signup:'Create account',about:'About',privacy:'Privacy'}[page]||'Page not found')+' · Hidayah FM';
 try{let html;switch(page){case'home':html=await home();break;case'quran':html=quran(params);break;case'read':html=await reader(parts[1],params);break;case'search':html=await search(params);break;case'tracks':html=tracks(params);break;case'reciters':html=intro('FAMILIAR VOICES. TIMELESS VERSES.','Find your reciter','Choose a voice and begin listening.')+`<div class="reciter-grid section">${state.reciters.map(reciterCard).join('')}</div>`;break;case'library':html=await library(params);break;case'playlist':html=await playlist(parts[1]);break;case'account':html=await account();break;case'login':html=auth();break;case'signup':html=auth(true);break;case'about':html=about();break;case'privacy':html=about(true);break;default:html=empty('A different path','This page could not be found.','<a class="button primary" href="#/home">Return home</a>');}
 if(version!==state.routeVersion)return;$('#main').innerHTML=html;syncPlaying();window.scrollTo(0,0);if(page==='quran')updateSurahs();if(page==='home')refreshPrayer();if(page==='read'&&params.has('ayah'))$('#ayah-'+Number(params.get('ayah')))?.scrollIntoView({block:'center'});if(page==='account'&&params.get('section')==='preferences')$('#preferences')?.scrollIntoView({block:'start'});
 }catch(e){if(version===state.routeVersion)$('#main').innerHTML=empty('Something interrupted your visit',e.message,'<button class="button primary" data-action="retry">Try again</button>');}
}

function source(item){
 Player.audio.pause();const url=safeUrl(item.link_url);if(!url)return toast('A source has not been added for this recording.');
 const id=videoId(item);if(!id){window.open(url,'_blank','noopener,noreferrer');return;}
 dialog(item.title,`<p class="dialog-copy">${esc(item.subtitle)} · Source recording on YouTube</p><iframe class="source-frame" title="${esc(item.title)} — YouTube player" src="https://www.youtube-nocookie.com/embed/${id}?rel=0" allow="encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p class="dialog-copy">If the video is unavailable here, open the original recording.</p><div class="modal-actions"><a class="button ghost small" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('external')}Open on YouTube</a>${actionButton('plus','Save to playlist','add-playlist',itemKey(item),'primary small')}</div>`);
}
function createPlaylist(item=null){if(!requireUser())return;dialog('A new space for your favourites',`<form class="modal-form" id="playlist-form" ${item?`data-add-key="${itemKey(item)}"`:''}><label class="field-label">Playlist name<input class="field" name="name" placeholder="e.g. Quiet mornings" maxlength="60" required autofocus></label><p class="form-error" role="alert"></p><div class="modal-actions"><button class="button ghost" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Create playlist</button></div></form>`);}
async function addToPlaylist(item){if(!requireUser())return;await loadLibrary();dialog('Save to a playlist',`<p class="dialog-copy">${esc(item.title)}</p>${state.playlists.map(p=>`<button class="playlist-choice" data-action="choose-playlist" data-id="${p.id}" data-key="${itemKey(item)}">${icon('queue')}<span>${esc(p.name)}</span>${icon('plus')}</button>`).join('')}<div class="modal-actions">${actionButton('plus','New playlist','new-playlist-item',itemKey(item),'primary')}</div>`);}
function renderQueue(){const panel=$('#queue-panel');panel.innerHTML=`<div class="row-between"><h2>Your listening queue</h2>${b('close','queue','Close queue')}</div><p class="reader-notice">${Player.queue.length} recitations · ${Player.shuffle?'Shuffle on':'In order'}</p>${Player.queue.length?Player.queue.map((item,i)=>`<div class="queue-row ${i===Player.index?'active':''}"><button data-action="queue-select" data-index="${i}">${icon(i===Player.index?'volume':'play')}<span class="queue-text"><strong>${esc(item.title)}</strong><small>${esc(item.subtitle)}</small></span></button>${b('close','queue-remove','Remove '+item.title+' from queue',`data-index="${i}" ${i===Player.index?'disabled':''}`)}</div>`).join(''):'<p class="dialog-copy section">Play a recitation, or add one from its more-options menu.</p>'}`;}
function syncNowPlaying(){
 const title=$('.now-dialog-title');if(!title)return;const item=Player.current;if(!item){closeDialog();return;}
 title.textContent=item.title;$('.now-dialog-art').textContent=item.title_ar||'سكينة';$('.now-dialog-subtitle').textContent=item.subtitle;
 const read=$('#dialog-read');if(read){read.hidden=item.type!=='surah';read.href='#/read/'+item.id;}
 for(const [id,on,label]of [['dialog-shuffle',Player.shuffle,'Shuffle'],['dialog-repeat',Player.repeat!=='off','Repeat: '+Player.repeat]]){const button=$('#'+id);if(button){button.classList.toggle('active',on);button.setAttribute('aria-pressed',String(on));button.setAttribute('aria-label',label);button.title=label;}}
 if($('#dialog-time'))$('#dialog-time').textContent=fmt(Player.audio.currentTime)+' / '+fmt(Player.audio.duration);
}
function nowPlaying(){
 const item=Player.current;if(!item)return toast('Choose a recitation to begin.');
 dialog('Now playing',`<div class="now-dialog-art arabic" lang="ar">${esc(item.title_ar||'سكينة')}</div><h3 class="now-dialog-title">${esc(item.title)}</h3><p class="now-dialog-subtitle">${esc(item.subtitle)}</p><div class="row-between"><span id="dialog-time">${fmt(Player.audio.currentTime)} / ${fmt(Player.audio.duration)}</span><label class="field-label">Speed<select id="playback-speed" aria-label="Playback speed">${[0.75,1,1.25,1.5,2].map(v=>`<option value="${v}" ${Player.audio.playbackRate===v?'selected':''}>${v}×</option>`).join('')}</select></label></div><div class="dialog-player-controls">${b('shuffle','shuffle','Shuffle','id="dialog-shuffle"')}${b('previous','previous','Previous recitation')}${actionButton('play',Player.audio.paused?'Play':'Pause','toggle-play',null,'primary')}${b('next','next','Next recitation')}${b('repeat','repeat','Repeat: '+Player.repeat,'id="dialog-repeat"')}</div><div class="modal-actions"><a id="dialog-read" class="button ghost" href="#/read/${item.id}" ${item.type==='surah'?'':'hidden'}>${icon('book')}Read</a>${actionButton('moon','Sleep timer','sleep',null,'ghost')}</div>`);
 syncNowPlaying();
}
function confirmAction(title,message,action,button='Confirm'){dialog(title,`<p class="dialog-copy">${esc(message)}</p><div class="modal-actions"><button class="button ghost" data-action="close-modal">Cancel</button><button class="button danger" data-action="${action}">${esc(button)}</button></div>`);}
async function logOut(deleting=false){
 const uid=session.user?.id;if(deleting)clearSession();Player.reset();clearSession();
 if(deleting)['hfm_playback_'+uid,'hfm_bookmark_'+uid].forEach(k=>localStorage.removeItem(k));
 state.settings=defaultSettings();writeStore('hfm_settings',state.settings);state.prayer=null;state.likes.clear();state.playlists=[];state.items.clear();state.viewItems=[];
 renderSidebar();history.replaceState(null,'','/#/login');await route();toast(deleting?'Your account has been deleted.':'You have been signed out.');
}
async function openAccount(){
 const owner=session.user.id;
 const [me,prefs,saved]=await Promise.all([api('/auth/me'),api('/auth/settings'),api('/auth/state')]);
 if(owner!==session.user?.id)return;
 saveSession({...session,user:me.user});state.settings={...defaultSettings(),...prefs.settings};writeStore('hfm_settings',state.settings);
 if(saved.bookmark)writeStore('hfm_bookmark_'+owner,saved.bookmark);else localStorage.removeItem('hfm_bookmark_'+owner);
 if(saved.playback)writeStore('hfm_playback_'+owner,saved.playback);
 if(!catalogueLoaded){const [s,r,t]=await Promise.all([api('/surahs'),api('/reciters'),api('/tracks?limit=200')]);if(owner!==session.user?.id)return;state.surahs=s.surahs;state.reciters=r.reciters;state.tracks=t.tracks;catalogueLoaded=true;}
 await loadLibrary();Player.restore();renderSidebar();
}

document.addEventListener('click',async e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();return;}
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,item=state.items.get(el.dataset.key);if(el.tagName==='A')return;
 try{switch(action){
 case'menu':{const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#menu-scrim').hidden=!open;break;}
 case'reset-password':location.assign('/reset-password.html');break;
 case'close-modal':closeDialog();break;case'retry':await route();break;
 case'play':if(item){if(itemKey(item)===itemKey(Player.current))Player.toggle();else await Player.play(item,state.viewItems.some(x=>itemKey(x)===itemKey(item))?state.viewItems:[item]);}break;
 case'source':if(item)source(item);break;
 case'toggle-play':Player.toggle();break;case'previous':Player.step(-1);break;case'next':Player.step(1);break;
 case'shuffle':Player.toggleShuffle();break;case'repeat':Player.toggleRepeat();break;case'mute':Player.mute();break;
 case'like':case'like-current':{if(!requireUser())break;const it=item||Player.current;if(!it)break;el.disabled=true;try{const d=await api('/likes/toggle','POST',itemBody(it));if(d.liked)state.likes.add(itemKey(it));else state.likes.delete(itemKey(it));syncLikes();toast(d.liked?'Saved to your liked recitations':'Removed from liked recitations');if(location.hash.includes('tab=liked'))await route();}finally{el.disabled=false;}break;}
 case'create-playlist':createPlaylist();break;case'new-playlist-item':createPlaylist(item);break;case'add-playlist':if(item)await addToPlaylist(item);break;
 case'choose-playlist':el.disabled=true;try{await api('/playlists/'+el.dataset.id+'/items','POST',itemBody(item));await loadLibrary();closeDialog();toast('Added to your playlist');}finally{el.disabled=false;}break;
 case'item-menu':if(item)dialog(item.title,`<div class="stack">${item.audio_url?actionButton('queue','Add to listening queue','enqueue',itemKey(item),'ghost'):actionButton('external','Open recording source','source',itemKey(item),'ghost')}${actionButton('plus','Save to a playlist','add-playlist',itemKey(item),'ghost')}${item.type==='surah'?`<a class="button ghost" href="#/read/${item.id}">${icon('book')}Read this surah</a>`:''}</div>`);break;
 case'enqueue':Player.enqueue(item);closeDialog();break;
 case'queue':$('#queue-panel').hidden=!$('#queue-panel').hidden;if(!$('#queue-panel').hidden)renderQueue();break;
 case'queue-select':Player.select(Number(el.dataset.index));break;case'queue-remove':Player.remove(Number(el.dataset.index));break;
 case'now':nowPlaying();break;
 case'sleep':dialog('Rest easy',`<p class="dialog-copy">Pause the recitation after a little while.${Player.sleepDeadline?` Timer ends at ${new Date(Player.sleepDeadline).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}.`:''}</p><div class="sleep-options">${[5,15,30,45,60,90].map(n=>`<button class="button ghost" data-action="set-sleep" data-minutes="${n}">${n} min</button>`).join('')}</div><button class="button ghost small" data-action="set-sleep" data-minutes="0">Turn off timer</button>`);break;
 case'set-sleep':Player.setSleep(Number(el.dataset.minutes));closeDialog();toast(Number(el.dataset.minutes)?'Sleep timer set for '+el.dataset.minutes+' minutes':'Sleep timer off');break;
 case'surah-filter':state.surahFilter=el.dataset.filter;updateSurahs();break;
 case'quran-list':case'quran-grid':state.quranView=action==='quran-list'?'list':'grid';writeStore('hfm_quran_view',state.quranView);updateSurahs();break;
 case'play-all':{const list=state.viewItems.filter(x=>x.audio_url);if(!list.length){toast('These recordings open on their source websites.');break;}await Player.play(list[0],list);break;}
 case'remove-item':await api('/playlists/'+currentPlaylist.id+'/items/'+el.dataset.entry,'DELETE');await loadLibrary();await route();toast('Removed from playlist');break;
 case'move-up':case'move-down':{const i=Number(el.dataset.index),j=i+(action==='move-up'?-1:1);if(j<0||j>=state.viewItems.length)break;const items=[...state.viewItems];[items[i],items[j]]=[items[j],items[i]];await api('/playlists/'+currentPlaylist.id+'/order','PUT',{entry_ids:items.map(x=>x.entry_id)});await route();break;}
 case'rename-playlist':dialog('Rename playlist',`<form id="rename-form" class="modal-form"><label class="field-label">Playlist name<input class="field" name="name" value="${esc(currentPlaylist.name)}" maxlength="60" required></label><p class="form-error" role="alert"></p><button class="button primary" type="submit">Save name</button></form>`);break;
 case'delete-playlist':confirmAction('Delete this playlist?','The playlist and its saved entries will be removed. Your liked recitations will remain.','confirm-delete-playlist','Delete playlist');break;
 case'confirm-delete-playlist':await api('/playlists/'+currentPlaylist.id,'DELETE');await loadLibrary();closeDialog();location.hash='#/library';toast('Playlist deleted');break;
 case'clear-history':confirmAction('Clear listening history?','Your history and saved completion progress will be cleared.','confirm-clear-history','Clear history');break;
 case'confirm-clear-history':await api('/history','DELETE');closeDialog();await route();toast('Listening history cleared');break;
 case'show-password':{const input=$('input',el.parentElement),show=input.type==='password';input.type=show?'text':'password';el.textContent=show?'Hide':'Show';el.setAttribute('aria-label',show?'Hide password':'Show password');break;}
 case'bookmark-ayah':{const bookmark={surah:readerSurah.id,ayah:Number(el.dataset.ayah),name:readerSurah.name_en};await api('/auth/bookmark','PUT',bookmark);writeStore('hfm_bookmark_'+session.user.id,bookmark);toast('Reading bookmark saved');break;}
 case'copy-ayah':{const a=readerAyahs.find(a=>a.number===Number(el.dataset.ayah));if(a){await navigator.clipboard.writeText(a.arabic+'\n\n'+a.english+'\nQuran '+readerSurah.id+':'+a.number+' · Sahih International translation');toast('Verse copied');}break;}
 case'refresh-prayer':state.prayer=null;if($('#prayer-home'))$('#prayer-home').innerHTML=prayerMarkup();await refreshPrayer();break;
 case'logout':await logOut();break;
 case'export':{const data=await api('/auth/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='hidayah-fm-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your data export is ready');break;}
 case'delete-account':dialog('Delete your account?',`<form id="delete-account-form" class="modal-form"><p>This permanently removes your account, playlists, likes, and history from this installation.</p>${passwordField('Confirm your password','password')}<label class="field-label">Type DELETE to confirm<input class="field" name="confirmation" pattern="DELETE" required autocomplete="off"></label><p class="form-error" role="alert"></p><button class="button danger" type="submit">Permanently delete account</button></form>`);break;
 }}catch(error){toast(error.message)}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));
 if(form.id==='global-search'){location.hash='#/search'+(data.q.trim()?'?q='+encodeURIComponent(data.q.trim()):'');$('#global-search input').blur();return;}
 const submit=$('button[type=submit]',form),error=$('.form-error',form);if(error)error.textContent='';if(submit)submit.disabled=true;
 try{switch(form.id){
 case'auth-form':{if(form.dataset.mode==='signup'&&data.password!==data.confirm)throw new Error('Passwords do not match.');const d=await api('/auth/'+form.dataset.mode,'POST',data);Player.reset();saveSession(d);await openAccount();history.replaceState(null,'','/#/home');await route();toast('Welcome, '+d.user.name.split(' ')[0]);break;}
 case'playlist-form':{const pl=await api('/playlists','POST',{name:data.name.trim()});if(form.dataset.addKey)await api('/playlists/'+pl.id+'/items','POST',itemBody(state.items.get(form.dataset.addKey)));await loadLibrary();closeDialog();location.hash='#/playlist/'+pl.id;toast('Playlist created');break;}
 case'rename-form':await api('/playlists/'+currentPlaylist.id,'PATCH',{name:data.name.trim()});await loadLibrary();closeDialog();await route();toast('Playlist renamed');break;
 case'profile-form':{const d=await api('/auth/me','PATCH',{name:data.name});saveSession({...session,user:d.user});renderSidebar();toast('Profile saved');break;}
 case'password-form':{if(data.new_password!==data.confirm)throw new Error('New passwords do not match.');const d=await api('/auth/change-password','POST',data);saveSession(d);form.reset();toast('Password changed. Other sessions have been signed out.');break;}
 case'preferences-form':{if(Boolean(data.city.trim())!==Boolean(data.country.trim()))throw new Error('Enter both a city and country for prayer times.');const settings={city:data.city.trim(),country:data.country.trim(),method:Number(data.method),reciter_id:Number(data.reciter_id),translation:data.translation==='on'};if(session.token)await api('/auth/settings','PUT',settings);state.settings=settings;writeStore('hfm_settings',settings);state.prayer=null;toast('Preferences saved');break;}
 case'delete-account-form':if(data.confirmation!=='DELETE')throw new Error('Type DELETE to confirm.');await api('/auth/me','DELETE',{password:data.password});closeDialog();await logOut(true);break;
 }}catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='surah-search'){state.surahQuery=e.target.value;updateSurahs();}});
document.addEventListener('change',async e=>{try{switch(e.target.id){case'reciter-select':state.settings.reciter_id=Number(e.target.value);writeStore('hfm_settings',state.settings);if(session.token)await api('/auth/settings','PUT',state.settings);updateSurahs();break;case'juz-filter':state.juz=e.target.value;updateSurahs();break;case'playback-speed':Player.setSpeed(e.target.value);break;case'translation-toggle':{const checkbox=e.target,previous=state.settings.translation,next=checkbox.checked;checkbox.disabled=true;try{const settings={...state.settings,translation:next};await api('/auth/settings','PUT',settings);state.settings=settings;writeStore('hfm_settings',settings);$$('.translation').forEach(p=>p.hidden=!next);}catch(error){checkbox.checked=previous;throw error;}finally{checkbox.disabled=false;}break;}case'verse-jump':$('#ayah-'+Number(e.target.value))?.scrollIntoView({block:'center',behavior:'smooth'});break;}}catch(error){toast(error.message)}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search input').focus();}if(e.code==='Space'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(e.target.tagName)&&!e.target.isContentEditable&&!$('#modal').open){e.preventDefault();Player.toggle();}if(e.key==='Escape'){$('#queue-panel').hidden=true;$('#sidebar').classList.remove('open');$('#menu-scrim').hidden=true;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
$('#modal').addEventListener('close',()=>{$('#modal-content').innerHTML='';});
window.addEventListener('hashchange',route);
window.addEventListener('player-change',syncPlaying);
window.addEventListener('player-time',()=>{if($('#dialog-time'))$('#dialog-time').textContent=fmt(Player.audio.currentTime)+' / '+fmt(Player.audio.duration)});
window.addEventListener('session-expired',()=>{logOut().then(()=>toast('Your session expired. Please sign in again.'));});
window.addEventListener('session-changed',async()=>{Player.reset();state.likes.clear();state.playlists=[];state.items.clear();state.routeVersion++;if(session.user){try{await openAccount();await route();}catch(e){toast(e.message)}}else await logOut();});
async function init(){
 $('#main-nav').innerHTML=nav.map(([path,label,ic])=>`<a class="nav-link" data-nav="${path}" href="#/${path}">${icon(ic)}${label}</a>`).join('');
 $('.mobile-nav').innerHTML=nav.map(([path,label,ic])=>`<a data-nav="${path}" href="#/${path}">${icon(ic)}${path==='quran'?'Quran':path==='library'?'Library':label}</a>`).join('');hydrate();
 try{$('#hijri-date').textContent=new Intl.DateTimeFormat('en-GB-u-ca-islamic',{day:'numeric',month:'long',year:'numeric'}).format(new Date());}catch{}
 const legacy={home:'home',quran:'quran',library:'library','now-playing':'home',account:'account',login:'login',signup:'signup'};const name=location.pathname.split('/').pop().replace('.html','');if(!location.hash&&legacy[name])history.replaceState(null,'','/#/'+legacy[name]+location.search);
 try{if(session.token)await openAccount();renderSidebar();await route();}
 catch(e){if(!session.token){await route();toast(e.message);}else $('#main').innerHTML=empty('Let’s get you connected',e.message,'<button class="button primary" data-action="reload-app">Retry connection</button><button class="button ghost" data-action="logout">Sign out</button>');}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reload-app"]'))location.reload();});
init();
